mapper.select:
SELECT l.lecture_id as lectureId, l.thumbnail, l.name as title, u.nickname as nickname, l.introduction, l.price, l.discount_rate as discountRate, COALESCE(r.review_count, 0) as reviewNum, COALESCE(r.avg_rating, 0.0) as avgReviewRate, COALESCE(e.student_count, 0) as studentNum, l.difficulty, l.upload_date as uploadDate FROM lecture l INNER JOIN lecture_bookmark b ON l.lecture_id = b.lecture_id LEFT JOIN user u ON l.uploader_id = u.user_id LEFT JOIN ( SELECT lecture_id, COUNT(*) as review_count, AVG(CAST(review_rate AS DECIMAL(3,2))) as avg_rating FROM review GROUP BY lecture_id ) r ON l.lecture_id = r.lecture_id LEFT JOIN ( SELECT lecture_id, COUNT(*) as student_count FROM user_lecture GROUP BY lecture_id ) e ON l.lecture_id = e.lecture_id WHERE b.user_id = #{userId}
AND l.price = 0
AND l.price > 0
LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE
FROM lecture_bookmark
WHERE user_id = #{userId}
  AND lecture_id = #{lectureId}

DELETE
FROM review
WHERE review_id = #{reviewId}
  and writer_id = #{writerId}

mapper.update:
UPDATE review
SET review_rate = #{reviewRate},
    content     = #{content},
    edite_date  = NOW()
WHERE review_id = #{reviewId}
  AND writer_id = #{writerId}

mapper.select:
SELECT l.lecture_id as lectureId, l.name as title, l.thumbnail, l.price, l.discount_rate as discountRate, COALESCE(r.review_count, 0) as reviewSum, COALESCE(r.avg_rating, 0.0) as reviewAVG, COALESCE(e.student_count, 0) as studentNum, l.upload_date as uploadDate FROM lecture l LEFT JOIN ( SELECT lecture_id, COUNT(*) as review_count, AVG(CAST(review_rate AS DECIMAL(3,2))) as avg_rating FROM review GROUP BY lecture_id ) r ON l.lecture_id = r.lecture_id LEFT JOIN ( SELECT lecture_id, COUNT(*) as student_count FROM user_lecture GROUP BY lecture_id ) e ON l.lecture_id = e.lecture_id WHERE l.uploader_id = #{userId}
AND l.price = 0
AND l.price > 0
ORDER BY l.upload_date DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM lecture l WHERE l.uploader_id = #{userId}
AND l.price = 0
AND l.price > 0

SELECT EXISTS(
    SELECT 1 FROM user_lecture 
    WHERE user_id = #{userId} AND lecture_id = #{lectureId}
)
